theme.additional_css:
/* ─── Sidebar Theme: Additional Styling ─── */
:root[data-nav-position="left"] [data-nav="root"] {
  background: oklch(0.16 0.025 260 / 0.95) !important;
  backdrop-filter: blur(30px) saturate(1.4);
  border-right: 1px solid oklch(0.35 0.02 260 / 0.2);
  box-shadow: 2px 0 30px oklch(0 0 0 / 0.3);
}
:root[data-nav-position="left"] [data-nav="root"] button { min-height: 48px !important; margin: 2px 4px !important; font-size: 14px !important; }
:root[data-nav-position="left"] [data-nav="root"] button:hover { background: oklch(0.30 0.03 260 / 0.4) !important; }
:root[data-nav-position="left"] main { padding-top: 1.5rem !important; }
:root[data-header-style="compact"] .glass-header { background: oklch(0.20 0.02 260 / 0.6) !important; backdrop-filter: blur(20px); border-bottom: 1px solid oklch(0.30 0.02 260 / 0.15); }
.glass-card { transition: border-color 0.3s ease, box-shadow 0.3s ease, transform 0.2s ease; }
.glass-card:hover { border-color: oklch(from var(--accent) l c h / 0.15); transform: translateY(-1px); }
@media (max-width: 768px) {
  :root[data-nav-position="left"] { --layout-nav-width: 0px; }
  :root[data-nav-position="left"] [data-nav="root"] {
    bottom: 0 !important; top: auto !important; left: 50% !important; right: auto !important;
    transform: translateX(-50%) !important; width: auto !important; max-width: calc(100vw - 1rem) !important;
    flex-direction: row !important; border-radius: 9999px !important; border-right: none !important;
  }
  :root[data-nav-position="left"] [data-nav="root"] .flex.items-center { flex-direction: row !important; }
  :root[data-nav-position="left"] [data-nav="root"] > div { flex-direction: row !important; height: auto !important; }
  :root[data-nav-position="left"] main, :root[data-nav-position="left"] .page-content { padding-left: 1rem !important; }
  :root[data-nav-position="left"] .glass-header { padding-left: 0 !important; }
}
